import{_ as a,C as n,o,c as i,E as r,a2 as d}from"./chunks/framework.Cm6XCzck.js";const b=JSON.parse('{"title":"TMPA–FCoP–CodeFlowMu Implementation Case — Draft I0.7","description":"","frontmatter":{"title":"TMPA–FCoP–CodeFlowMu Implementation Case — Draft I0.7","outline":"deep"},"headers":[],"relativePath":"en/publications/implementation-case-i0.7/part-01.md","filePath":"en/publications/implementation-case-i0.7/part-01.md","lastUpdated":1786282064000}'),s={name:"en/publications/implementation-case-i0.7/part-01.md"};function c(l,e,p,u,h,m){const t=n("ArticleCover");return o(),i("div",null,[r(t,{image:"/assets/covers/implementation-case.svg",kicker:"Engineering Case",title:"TMPA Implementation Case",summary:"A locked CodeFlowMu V1.4.1 product run covering all TMPA Core S0.5 criteria, with retained WP-13 governance evidence.",version:"I0.7",status:"S0.5 product evidence draft · 14/14 PASS",languageHref:"/zh/publications/implementation-case-i0.7",languageLabel:"简体中文"}),e[0]||(e[0]=d(`<h1 id="tmpa-implementation-and-case-report" tabindex="-1">TMPA Implementation and Case Report <a class="header-anchor" href="#tmpa-implementation-and-case-report" aria-label="Permalink to &quot;TMPA Implementation and Case Report&quot;">​</a></h1><h2 id="tmpa-core-s0-5-fcop-3-2-4-codeflowmu-v1-4-1-and-wp-13" tabindex="-1">TMPA Core S0.5, FCoP 3.2.4, CodeFlowMu V1.4.1, and WP-13 <a class="header-anchor" href="#tmpa-core-s0-5-fcop-3-2-4-codeflowmu-v1-4-1-and-wp-13" aria-label="Permalink to &quot;TMPA Core S0.5, FCoP 3.2.4, CodeFlowMu V1.4.1, and WP-13&quot;">​</a></h2><blockquote><p><strong>Document Version:</strong> Draft I0.7<br><strong>Status:</strong> Author-produced implementation and case report<br><strong>Normative Target:</strong> <a href="/joinwell52/en/publications/tmpa-core-specification-s0.5">TMPA Core Specification S0.5</a><br><strong>Product Under Test:</strong> CodeFlowMu V1.4.1, commit <code>1cd403537136b3e915c4646cd306983eaca1d2ce</code><br><strong>Evidence Capture:</strong> 2026-08-09, Asia/Shanghai<br><strong>Formal Evidence Package:</strong> <code>tmpa-i0.7-codeflowmu-v1.4.1-evidence-20260809.zip</code><br><strong>Archive SHA-256:</strong> <code>06f34ce7c6b5008b9adeedc45f68541ce5f3ecff6613c80ff3bb05a12fa61b34</code><br><strong>Authority Boundary:</strong> This report is evidentiary and non-normative. Only the Core Specification defines TMPA requirements.</p></blockquote><h2 id="abstract" tabindex="-1">Abstract <a class="header-anchor" href="#abstract" aria-label="Permalink to &quot;Abstract&quot;">​</a></h2><p>I0.7 evaluates a public, commit-locked CodeFlowMu V1.4.1 source tree against all fourteen mandatory conformance criteria in TMPA Core S0.5. Under the fixed source and test bundle, the product matrix records <strong>14 PASS, 0 PARTIAL, 0 NOT RUN, and 0 FAIL</strong>. The external product fixture passes 15/15 assertions, CodeFlowMu&#39;s built-in TMPA suite passes 19/19 tests, Runtime records 1,446 passed / 0 failed / 1 skipped tests, Shell records 775/775, FCoP records 1,210 passed / 2 skipped tests, and the protocol and type-check tracks exit successfully.</p><p>The result upgrades the I0.6 local baseline and the retained CodeFlowMu V1.4.0 repair baseline. V1.4.0 produced 12 PASS / 2 FAIL because C06 did not keep lifecycle completion separate from independent acceptance and C12 allowed an unauthorized decision to clear a review conflict. V1.4.1 repairs those two boundaries without weakening C03 or C10. The V1.4.0 archive remains historical evidence and is not the formal I0.7 publication package.</p><p>The strongest supportable conclusion is <strong>author-local demonstrated product conformance under a fixed bundle</strong>. It is not independent certification, independent adoption, a formal proof for arbitrary inputs, or proof that multi-agent hallucinations have been eliminated. WP-13 remains a separate bounded case demonstrating evidence gating and role-separated review of an initially unverified completion claim.</p><h1 id="_1-scope-and-research-questions" tabindex="-1">1. Scope and Research Questions <a class="header-anchor" href="#_1-scope-and-research-questions" aria-label="Permalink to &quot;1. Scope and Research Questions&quot;">​</a></h1><p>I0.7 asks:</p><ol><li>Does the locked CodeFlowMu V1.4.1 product run satisfy each mandatory S0.5 criterion C01–C14?</li><li>Do the V1.4.1 changes close the two V1.4.0 failures without collapsing distinct governance criteria?</li><li>How do TMPA, FCoP, CodeFlowMu, and WP-13 relate without confusing theory, protocol, application, and case evidence?</li><li>Which limits remain before the result can be called independently validated or adopted?</li></ol><p>The unit of judgment is a criterion-bound claim over a fixed source and evidence bundle. Four maturity levels remain separate:</p><table tabindex="0"><thead><tr><th>Level</th><th>Meaning in I0.7</th><th style="text-align:right;">Reached?</th></tr></thead><tbody><tr><td>Specified</td><td>Defined normatively by TMPA Core S0.5</td><td style="text-align:right;">Yes</td></tr><tr><td>Implemented</td><td>A corresponding product mechanism exists</td><td style="text-align:right;">Yes</td></tr><tr><td>Demonstrated</td><td>An author-run execution produced inspectable evidence</td><td style="text-align:right;">Yes, for C01–C14 under this bundle</td></tr><tr><td>Independently Adopted</td><td>A separate organization adopted and validated the mechanism</td><td style="text-align:right;">No</td></tr></tbody></table><h1 id="_2-architecture-and-evidence-boundaries" tabindex="-1">2. Architecture and Evidence Boundaries <a class="header-anchor" href="#_2-architecture-and-evidence-boundaries" aria-label="Permalink to &quot;2. Architecture and Evidence Boundaries&quot;">​</a></h1><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>TMPA Architecture Paper</span></span>
<span class="line"><span>        ↓ theory and governance model</span></span>
<span class="line"><span>TMPA Core S0.5</span></span>
<span class="line"><span>        ↓ normative object, Reader, and conformance contract</span></span>
<span class="line"><span>FCoP protocol</span></span>
<span class="line"><span>        ↓ file-based coordination profile and reference implementation</span></span>
<span class="line"><span>CodeFlowMu application</span></span>
<span class="line"><span>        ↓ runtime, roles, workflow, recovery, and audit behavior</span></span>
<span class="line"><span>WP-13 bounded field case</span></span></code></pre></div><p>TMPA is the architecture and governance theory. FCoP is a reusable file-based coordination protocol, not an application and not a package-installation claim. Its <code>fcop</code> and <code>fcop-mcp</code> packages are reference implementations of the protocol. CodeFlowMu is the downstream application evaluated here. WP-13 is one bounded workflow case inside that engineering lineage; it cannot stand in for the complete C01–C14 product run.</p><p>Conceptual dependency and historical development remain distinct:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CONCEPTUAL: TMPA → FCoP → CodeFlowMu / other applications</span></span>
<span class="line"><span>HISTORICAL: XiaoDian practice → early TMPA → FCoP extraction</span></span>
<span class="line"><span>                                   → CodeFlowMu → current TMPA formalization</span></span></code></pre></div><p>XiaoDian AI remains part of the engineering lineage and a candidate field-evidence source. I0.7 makes no new XiaoDian conformance claim because no XiaoDian S0.5 bundle was executed in this run.</p><h1 id="_3-fixed-sources-and-evidence-design" tabindex="-1">3. Fixed Sources and Evidence Design <a class="header-anchor" href="#_3-fixed-sources-and-evidence-design" aria-label="Permalink to &quot;3. Fixed Sources and Evidence Design&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Source</th><th>Fixed identity</th><th>Role in I0.7</th><th>Boundary</th></tr></thead><tbody><tr><td>TMPA Core</td><td>S0.5</td><td>Normative C01–C14 target</td><td>Specification, not product evidence</td></tr><tr><td>CodeFlowMu</td><td>V1.4.1, commit <code>1cd403537136b3e915c4646cd306983eaca1d2ce</code></td><td>Product under test</td><td>Publicly retrievable; clean detached checkout before initialization</td></tr><tr><td>FCoP</td><td>3.2.4, commit <code>da79dfefd99f597c9e422ce9edec22157f915a21</code></td><td>Protocol and reference baseline</td><td>Publicly retrievable clean checkout</td></tr><tr><td>External fixture</td><td>15 mandatory assertions</td><td>Product-level C01–C14 evaluation</td><td>Fixed test construction, not arbitrary-input proof</td></tr><tr><td>WP-13 V3</td><td>Previously published package</td><td>Multi-agent evidence-gating case</td><td>Separate author-produced case evidence</td></tr></tbody></table><p>The original local CodeFlowMu and FCoP worktrees were dirty but were not modified during evidence collection. Testing used detached, fixed checkouts. CodeFlowMu was clean before product initialization; initialization-generated files are separately recorded in <code>manifests/codeflowmu-post-initialization-status.txt</code>. No push, release, or tag occurred during evidence capture.</p><p>The formal public package is V1.4.1 plus its external SHA-256 file. The V1.4.0 package records the repair-before state—12 PASS / 2 FAIL—and is retained outside the formal I0.7 main package unless a reviewer requests a repair comparison.</p>`,22))])}const g=a(s,[["render",c]]);export{b as __pageData,g as default};
